          steps = "Swim to the iceberg off the Grizzly Hills coast and loot the Glimmerfin Scale from the Glimmerfin Scout, then carry it to King Mrgl-Mrgl in Borean Tundra to open the hidden chain. It runs through crab meat, horker blubber, a deep-water pearl, a tamer battle and seaweed stalks, and finishes on the elite Great Mua'kin, so bring help for that one." },
        { speciesID = 2900, itemID = 183859, npcID = 171136, name = "Dal", petType = 1, source = "quest", sourceInfo = "|cFFFFD200Quest:|r A Stolen Stonefiend|n|cFFFFD200Zone:|r Revendreth|n", zone = "Revendreth" },
        { speciesID = 2928, itemID = 180839, npcID = 171667, name = "Helpful Glimmerfly", petType = 3, source = "quest", sourceInfo = "|cFFFFD200Quest:|r How to Catch a Glimmerfly|n|cFFFFD200Zone:|r Bastion", zone = "Bastion", waypoint = { 1533, 0.4280, 0.4270, "Helpful Glimmerfly" } },
        { speciesID = 3107, itemID = 186553, npcID = 179140, name = "Gurgl", petType = 1, source = "quest", sourceInfo = "|cFFFFD200Quest: |rGurgl and the Bandit|n|cFFFFD200Zone: |rEye of Azshara", zone = "Eye of Azshara", waypoint = { 790, 0.7320, 0.7500, "Gurgl" },
          steps = "Pick up Pets Detective from Breanni in Dalaran and use her cat Fiona to sniff out the hidden spies, which leads on to Zantini in the Eye of Azshara. Finish his short chain, beat Trainer Iris Greedsway, leader of the Violetsail poachers, in a pet battle, then hand the murloc back to Breanni to keep it." },
        { speciesID = 3237, itemID = 189585, npcID = 184923, name = "E'rnee", petType = 9, source = "quest", sourceInfo = "|cFFFFD200Quest:|r Can I Keep Him?", zone = "Zereth Mortis", waypoint = { 1970, 0.4920, 0.7180, "E'rnee" } },
    } },
    { source = "treasure", pets = {
